import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const TYPE_INCOME = '손익계산서';
const TYPE_ALLOCATION = '손익계산서 안분 현황';
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function optionalId(value: unknown, name: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값이 올바르지 않습니다.');
  }
  return text;
}

function numberOr(value: unknown, fallback: number): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 정보가 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr01004Controller {
  @Get('/management-income-statements')
  async listManagementIncomeStatements(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const query = checks.queryOf(req.query);
    const queryType = String(query['queryType'] ?? '');
    if (queryType !== TYPE_INCOME && queryType !== TYPE_ALLOCATION) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 구분을 선택하세요.');
    }
    const periodStart = String(query['periodStart'] ?? '');
    const periodEnd = String(query['periodEnd'] ?? '');
    if (periodStart === '' || periodEnd === '') {
      throw new ApiError(422, 'INVALID_PERIOD', '조회 기간을 입력하세요.');
    }
    if (!DATE_RE.test(periodStart) || !DATE_RE.test(periodEnd)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 기간 형식이 올바르지 않습니다.');
    }
    if (periodStart > periodEnd) {
      throw new ApiError(422, 'INVALID_PERIOD', '조회 시작일이 종료일보다 늦을 수 없습니다.');
    }
    const projectId = optionalId(query['projectId'], '프로젝트');
    const departmentId = optionalId(query['departmentId'], '부서');
    const page = numberOr(query['page'], 0);
    const size = Math.min(Math.max(numberOr(query['size'], DEFAULT_SIZE), 1), MAX_SIZE);

    return transaction(async (db) => {
      if (queryType === TYPE_INCOME) {
        // 전표 분개 테이블이 입력 스키마에 없어 집계할 수 없다 (todos 참고)
        return { items: [], page, size, total: 0 };
      }
      const params = {
        projectId,
        departmentId,
        limit: size,
        offset: page * size,
      };
      const where = `use_yn = '사용'
        AND (CAST(:projectId AS bigint) IS NULL OR project_id = CAST(:projectId AS bigint))
        AND (CAST(:departmentId AS bigint) IS NULL OR department_id = CAST(:departmentId AS bigint))`;
      const countRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM allocation_basis WHERE ' + where,
        { projectId, departmentId },
      );
      const items = await db.query(
        `SELECT basis_name AS "basisName",
          allocation_rate AS "allocationRate",
          CAST(NULL AS text) AS "accountName",
          CAST(NULL AS numeric) AS "amount"
        FROM allocation_basis
        WHERE ${where}
        ORDER BY allocation_basis_id
        LIMIT :limit OFFSET :offset`,
        params,
      );
      const total = Number((countRows[0] as Record<string, unknown>)['total']);
      return { items, page, size, total };
    });
  }
}

