import { useState } from 'react';
import {
  call,
  useData,
  Filters,
  Band,
  DataTable,
  Pager,
  Num,
  Field,
  Select,
  DateInput,
  LookupSelect,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;
const TYPES: [string, string][] = [
  ['손익계산서', '손익계산서'],
  ['손익계산서 안분 현황', '손익계산서 안분 현황'],
];

const EMPTY: Row = {
  queryType: '손익계산서 안분 현황',
  periodStart: '',
  periodEnd: '',
  projectId: '',
  departmentId: '',
};

export default function FnSfr01004Page({ role, notify }: PageProps) {
  const [form, setForm] = useState<Row>(EMPTY);
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page | undefined>(async () => {
    if (!applied) {
      return undefined;
    }
    return call<Page>('GET', '/management-income-statements', role, undefined, {
      ...applied,
      page,
      size: SIZE,
    });
  }, [applied, page, role]);

  function set(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  function search() {
    if (!form.periodStart || !form.periodEnd) {
      setFormError('조회 기간을 입력하세요.');
      return;
    }
    if (String(form.periodStart) > String(form.periodEnd)) {
      setFormError('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ ...form });
  }

  function reset() {
    setForm(EMPTY);
    setApplied(null);
    setPage(0);
    setFormError('');
  }

  const rows = data ? data.items : [];
  const isAllocation = applied ? applied.queryType === '손익계산서 안분 현황' : true;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 조건</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 구분" required>
            <Select value={form.queryType} onChange={(v) => set('queryType', v)} options={TYPES} />
          </Field>
          <Field label="조회 시작일" required>
            <DateInput value={form.periodStart} onChange={(v) => set('periodStart', v)} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={form.periodEnd} onChange={(v) => set('periodEnd', v)} />
          </Field>
          <Field label="안분 대상 프로젝트">
            <LookupSelect table="project" role={role} value={form.projectId} onChange={(v) => set('projectId', v)} />
          </Field>
          <Field label="안분 대상 부서">
            <LookupSelect table="department" role={role} value={form.departmentId} onChange={(v) => set('departmentId', v)} />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
      </section>
      <section className="box span-12">
        <h2>{isAllocation ? '안분 현황' : '관리용 손익계산서'}</h2>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0} />
        <DataTable
          rows={rows}
          empty={applied ? (loading ? '불러오는 중입니다.' : '조회된 데이터가 없습니다.') : '조회 조건을 입력하고 조회하세요.'}
          columns={[
            { key: 'basisName', label: '안분 기준명' },
            { key: 'allocationRate', label: '안분 비율(%)', render: (r) => <Num value={r.allocationRate} /> },
            { key: 'accountName', label: '계정과목명' },
            { key: 'amount', label: '집계 금액 또는 안분 금액', render: (r) => <Num value={r.amount} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
    </div>
  );
}
